export const ACL_LIFECYCLE_STATES=new Set(["idle","deferred","loading","ready","deactivated","destroyed"]);export const applyLifecycleState=(e,t)=>{if(!ACL_LIFECYCLE_STATES.has(t))throw TypeError(`[ACL] Unknown lifecycle state "${t}".`);e._state=t;let r="deferred"===t&&e?._ssrHydration;return e.setAttribute?.("aria-busy",!r&&("deferred"===t||"loading"===t)?"true":"false"),t};export const createLifecycleEventDetail=(e,t,r={})=>({component:e,tagName:t,props:e.$props,timestamp:Date.now(),...r});